arguments.command:
# Verify it's a valid ZIP and no placeholders remain
python3 -c "
import zipfile
import re
with zipfile.ZipFile('/root/event_announcement_ready.hwpx', 'r') as z:
    print('Valid ZIP, files:', len(z.namelist()))
    # Check no placeholders remain
    errors = []
    for name in z.namelist():
        try:
            content = z.read(name).decode('utf-8')
            remaining = re.findall(r'\{\{[^}]+\}\}', content)
            if remaining:
                errors.append(f'ERROR: Placeholders remain in {name}: {remaining}')
        except:
            pass
    if errors:
        for e in errors:
            print(e)
    else:
        print('No placeholders remain - SUCCESS')
    print('Verification complete')
"

